@startuml

class Agency {
  + Search(key: string) : void
}

class Property {
  + code: string
  + address: string
  + zipCode: string
  + city: string
  + area: int
  + ToString() : string
  + Contains(key: string) : boolean
  + Write() : void
}

class Garage extends Property {
  + numberOfParkingSpaces: int
}

class Apartment extends Property {
  + numberOfRooms: int
  + numberOfBathrooms: int
}

class Villa extends Apartment {
  + gardenSize: int
}

Agency "1" -- "*" Property : manages

@enduml

